    s = &s_sensors[idx];
    if(s->online == online) {
        if(!online) {
            return false;
        }
        if(s->value == value) {
            return false;
        }
    }

    s->online = online;
    if(online) {
        s->value = value;
        s->base_value = value;
        s->age_sec = 1;
        s->quality_pct = 95;
        s->severity = VG_SEV_OK;
#ifdef VG_HMI_BOARD
        s_net.acq_ok = true;
        if(strstr(s->name, "水浸") != NULL && value >= 1.0f) {
            s->severity = VG_SEV_CRIT;
            if(!s_alarm.active || strcmp(s_alarm.sensor_id, s->id) == 0) {
                set_alarm_from_sensor(s, VG_SEV_CRIT, "水浸告警", 1.0f,
                                     s_alarm.active ? s_alarm.duration_sec : 0);
            }
        }
        else if(strstr(s->name, "烟雾") != NULL && value >= 1.0f) {
            s->severity = VG_SEV_CRIT;
            if(!s_alarm.active || strcmp(s_alarm.sensor_id, s->id) == 0) {
                set_alarm_from_sensor(s, VG_SEV_CRIT, "烟雾告警", 1.0f,
                                     s_alarm.active ? s_alarm.duration_sec : 0);
            }
        }
#endif
        if(s->history_len < VG_HISTORY_LEN) {
            s->history[s->history_len++] = value;
        }
        else {
            memmove(&s->history[0], &s->history[1],
                    (VG_HISTORY_LEN - 1) * sizeof(float));
            s->history[VG_HISTORY_LEN - 1] = value;
        }
    }
    else {
        if(s->age_sec < 100000) {
            s->age_sec++;
        }
        s->quality_pct = 0;
        s->severity = VG_SEV_OFFLINE;
    }
    return true;
}

