/****************************************************************************
 * Runtime point-table alarm compare (no I/O).
 *
 * Empty cmp, or ge/le with both thresholds missing, means no analog alarm.
 * Offline uses consecutive read failures against fail_n (default 3).
 ****************************************************************************/

#ifndef __APP_VELAGUARD_VG_ALARM_EVAL_H
#define __APP_VELAGUARD_VG_ALARM_EVAL_H

#include <stdint.h>

enum vg_alarm_kind
{
  VG_ALARM_KIND_NONE = 0,
  VG_ALARM_KIND_WARN,
  VG_ALARM_KIND_CRIT,
  VG_ALARM_KIND_OFFLINE
};

struct vg_alarm_rule
{
  char cmp[4];
  uint8_t has_warn;
  uint8_t has_crit;
  float warn;
  float crit;
  uint8_t fail_n;
};

/* 0 = none. *thr_out is the threshold that fired (0 for offline). */
enum vg_alarm_kind vg_alarm_eval(const struct vg_alarm_rule *rule,
                                 int last_ok, uint8_t fail_streak,
                                 float value, float *thr_out);

uint8_t vg_alarm_fail_n(const struct vg_alarm_rule *rule);
int vg_alarm_kind_rank(enum vg_alarm_kind kind);

#endif

/****************************************************************************
 * app/velaguard/vg_alarm_eval.c
 ****************************************************************************/

#include "vg_alarm_eval.h"

#include <math.h>
#include <string.h>

#ifndef VG_ALARM_EQ_EPS
#  define VG_ALARM_EQ_EPS 0.0005f
#endif

uint8_t vg_alarm_fail_n(const struct vg_alarm_rule *rule)
{
  if (rule == NULL || rule->fail_n < 1)
    {
      return 3;
    }

  if (rule->fail_n > 20)
    {
      return 20;
    }

  return rule->fail_n;
}

int vg_alarm_kind_rank(enum vg_alarm_kind kind)
{
  switch (kind)
    {
      case VG_ALARM_KIND_CRIT:
        return 3;
      case VG_ALARM_KIND_OFFLINE:
        return 2;
      case VG_ALARM_KIND_WARN:
        return 1;
      default:
        return 0;
    }
}

static int eq_hit(float value, float thr)
{
  float d = value - thr;

  if (d < 0.0f)
    {
      d = -d;
    }

  return d <= VG_ALARM_EQ_EPS;
}

enum vg_alarm_kind vg_alarm_eval(const struct vg_alarm_rule *rule,
                                 int last_ok, uint8_t fail_streak,
                                 float value, float *thr_out)
{
  uint8_t need;
  const char *cmp;

  if (thr_out != NULL)
    {
      *thr_out = 0.0f;
    }

  if (rule == NULL)
    {
      return VG_ALARM_KIND_NONE;
    }

  need = vg_alarm_fail_n(rule);
  if (!last_ok)
    {
      if (fail_streak >= need)
        {
          return VG_ALARM_KIND_OFFLINE;
        }

      return VG_ALARM_KIND_NONE;
    }

  cmp = rule->cmp;
  if (cmp[0] == '\0')
    {
      return VG_ALARM_KIND_NONE;
    }

  if (strcmp(cmp, "eq") == 0)
    {
      if (rule->has_crit && eq_hit(value, rule->crit))
        {
          if (thr_out != NULL)
            {
              *thr_out = rule->crit;
            }

          return VG_ALARM_KIND_CRIT;
        }

      if (rule->has_warn && eq_hit(value, rule->warn))
        {
          if (thr_out != NULL)
            {
              *thr_out = rule->warn;
            }

          return VG_ALARM_KIND_WARN;
        }

      return VG_ALARM_KIND_NONE;
    }

  if (strcmp(cmp, "ge") == 0)
    {
      if (rule->has_crit && value >= rule->crit)
        {
          if (thr_out != NULL)
            {
              *thr_out = rule->crit;
            }

          return VG_ALARM_KIND_CRIT;
        }

      if (rule->has_warn && value >= rule->warn)
        {
          if (thr_out != NULL)
            {
              *thr_out = rule->warn;
            }

          return VG_ALARM_KIND_WARN;
        }

      return VG_ALARM_KIND_NONE;
    }

  if (strcmp(cmp, "le") == 0)
    {
      if (rule->has_crit && value <= rule->crit)
        {
          if (thr_out != NULL)
            {
              *thr_out = rule->crit;
            }

          return VG_ALARM_KIND_CRIT;
        }

      if (rule->has_warn && value <= rule->warn)
        {
          if (thr_out != NULL)
            {
              *thr_out = rule->warn;
            }

          return VG_ALARM_KIND_WARN;
        }

      return VG_ALARM_KIND_NONE;
    }

  return VG_ALARM_KIND_NONE;
}

#include <stdio.h>

#include "../vg_alarm_eval.h"

static int expect_true(int cond, const char *msg)
{
  if (!cond)
    {
      fprintf(stderr, "FAIL: %s\n", msg);
      return 1;
    }

  return 0;
}

int main(void)
{
  int fails = 0;
  struct vg_alarm_rule temp;
  struct vg_alarm_rule flood;
  struct vg_alarm_rule empty;
  float thr;
  enum vg_alarm_kind k;

  memset(&temp, 0, sizeof(temp));
  snprintf(temp.cmp, sizeof(temp.cmp), "ge");
  temp.has_warn = 1;
  temp.warn = 40.0f;
  temp.has_crit = 1;
  temp.crit = 55.0f;
  temp.fail_n = 3;

  memset(&flood, 0, sizeof(flood));
  snprintf(flood.cmp, sizeof(flood.cmp), "eq");
  flood.has_crit = 1;
  flood.crit = 1.0f;
  flood.fail_n = 3;

  memset(&empty, 0, sizeof(empty));
  empty.fail_n = 3;

  k = vg_alarm_eval(&temp, 1, 0, 39.9f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_NONE, "temp below warn");

  k = vg_alarm_eval(&temp, 1, 0, 40.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_WARN && thr > 39.0f, "temp warn");

  k = vg_alarm_eval(&temp, 1, 0, 55.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_CRIT && thr > 54.0f, "temp crit");

  k = vg_alarm_eval(&flood, 1, 0, 0.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_NONE, "flood 0");

  k = vg_alarm_eval(&flood, 1, 0, 1.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_CRIT && thr == 1.0f, "flood 1");

  k = vg_alarm_eval(&empty, 1, 0, 99.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_NONE, "empty cmp no analog");

  k = vg_alarm_eval(&temp, 0, 2, 0.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_NONE, "fail streak 2");

  k = vg_alarm_eval(&temp, 0, 3, 0.0f, &thr);
  fails += expect_true(k == VG_ALARM_KIND_OFFLINE, "fail streak 3");

  fails += expect_true(vg_alarm_fail_n(&empty) == 3, "default fail_n");
  fails += expect_true(vg_alarm_kind_rank(VG_ALARM_KIND_CRIT) >
                       vg_alarm_kind_rank(VG_ALARM_KIND_OFFLINE),
                       "crit ranks above offline");

  if (fails)
    {
      fprintf(stderr, "%d fail(s)\n", fails);
      return 1;
    }

  printf("test_alarm_eval: ok\n");
  return 0;
}

